"""Individually authored alternative scenes. No runtime text generation."""
VARIANTS={}


def add(pack,number,text,labels,signals,*,key='CORE',modes=(),note='基础玩法中的替代情境，不将未体验作为计分答案。'):
    VARIANTS.setdefault(pack,{}).setdefault(number,[]).append({
        'key':key,'text':text,'labels':labels,'signals':signals.split(),
        'modes':list(modes),'note':note})


add('gi', 1, '你已从蒙德城外开始一小段自由行动，眼前有未走过的高处、已发现仙灵与熟悉主路，也有可继续任务。先做什么？', ['走向未到过的高处，先看看能发现什么新地方', '按自己惦记的区域宝箱缺项跟完眼前仙灵，取回已知奖励', '接着走已经推进的任务，听清刚才人物的后续', '自己仍有精力，主动重走熟悉安全小路，享受已经认识的环境与日常带来的安定'], 'wanderer collector story_keeper cozy_resident', note='手写蒙德早期独立情境；按当前行动或真实过去解释，不要求新角色、舞台故事、家园或真人同游。')
add('gi', 2, '只用早期已经拥有的角色，你正站在一群会打的蒙德敌人前；现有切人和技能都可用，也有一份够用经验材料。先做什么？', ['把现有角色的元素与技能先后调整一轮，实际检验配合', '连着移动、普攻与切人，体验每次出手的直接反馈', '规定这小场每名现有角色出手一次就必须切人，不许一人连续进攻，实际试这种轮流限制', '先使用手头够用材料提升同一名已培养角色，再带他继续行动'], 'build_alchemist feedback_engine play_inventor growth_keeper', note='手写蒙德早期独立情境；按当前行动或真实过去解释，不要求新角色、舞台故事、家园或真人同游。')
add('gi', 3, '你已用现有角色走到蒙德附近安全处，故事语音有已开放条目，当前材料也够做一项培养。现在先做什么？', ['拿少用但已拥有的角色在熟悉敌人前试招，体验动作反馈', '用手头够用的经验或培养材料，给同一角色留一次持续提升', '按自定的巡路冒险家身份选现有队伍，先查已知道路再沿巡查路线走', '阅读已开放的角色故事与语音，把他的前后经历联系起来'], 'feedback_engine growth_keeper role_player story_keeper', note='手写蒙德早期独立情境；按当前行动或真实过去解释，不要求新角色、舞台故事、家园或真人同游。')
add('gi', 4, '当前已打开背包与角色菜单，手里有可用培养材料，也能自由到蒙德野外走动。现在先做什么？', ['核对已有材料与可达采集点，排好这一趟培养、出发与返回', '先使用够用材料提升正在培养的同一名角色', '让现有元素角色的出手先后互补，再到熟悉敌人前打出一轮', '先走进未探过的可达支路，不为材料收获而绕行'], 'systems_builder growth_keeper build_alchemist wanderer', note='手写蒙德早期独立情境；按当前行动或真实过去解释，不要求新角色、舞台故事、家园或真人同游。')
add('gi', 5, '一群已经会打的蒙德敌人就在眼前，现有角色都能切换，也能绕开去别处。现在先做什么？', ['用熟悉角色反复练一次已见攻击的闪避', '调整现有元素角色的技能先后，实际打出一轮配合', '规定这小场不用普攻、只许已有角色战技和躲避，亲自试这种限制怎样改变战斗', '转去自己未到过的可达小路，看看那里有什么'], 'practice_seeker build_alchemist play_inventor wanderer', note='手写蒙德早期独立情境；按当前行动或真实过去解释，不要求新角色、舞台故事、家园或真人同游。')
