add('lol', 6, '不要求真人队友或真人对手。当前在允许自由尝试的练习或自定义场合，一波兵线到眼前，自己的技能与装备可用。先做什么？', ['把技能使用、收兵与继续推进的先后排顺', '对照敌人与技能指示，验证一次范围、阻挡或触发关系', '亲手接一串移动与命中，体验它们的连续反馈', '在允许自由试用的这段，规定只用普攻与移动处理兵线、不准主动技能，实际试限制后的处理'], 'systems_builder puzzle_breaker feedback_engine play_inventor', note='手写独立基础替代；不要求真人同伴、真人对手、排位、其他外观或指定英雄，9—12只回顾已经完成的行为。')
add('lol', 7, '当前在真人对手也参与、大家同意自由试用的普通大乱斗自定义局，刚在出生处获得购买机会，金币能买几件熟悉装备，尚未离开商店。先怎样选？', ['按当前技能与装备的相互作用，买下能组成配合的一件', '为接下来一段定只许普攻与移动、不准主动技能的限制，按这规则选择可买装备，再出发实际试用', '按自己喜欢的出手节奏购买，出发后体验动作与命中反馈', '针对当前真人对手与明确的胜负目标，完成这次装备准备'], 'build_alchemist play_inventor feedback_engine rank_worker', key='ARAM', modes=('aram',), note='手写普通大乱斗独立路径；英雄已由当局确定，购买限实际商店机会，真人协作有明确前提。')
add('lol', 7, '当前在允许自由试用的练习或自定义场合，已获得本模式允许的购买机会，金币能买几件熟悉装备；不要求真人对手。先怎样选并试用？', ['按装备与技能的相互作用，选出并使用一组配合', '为这段定每次普攻后先横移、不许站定连打的规则，按这限制选可用装备并实际试一段', '按自己喜欢的出手节奏选择，实际体验动作与命中反馈', '对照技能指示和敌人位置，选一件来验证范围或触发条件'], 'build_alchemist play_inventor feedback_engine puzzle_breaker', note='手写独立基础替代；不要求真人同伴、真人对手、排位、其他外观或指定英雄，9—12只回顾已经完成的行为。')
add('lol', 8, '当前在真人熟人约好的普通大乱斗自定义练习里，已用默认或已有外观出场，眼前暂时无交火。先做什么？', ['移动英雄并调整普通镜头，把当前地图与英雄组成自己的主题截图', '亲手接一次当前能用的技能，体验动作、声音与命中的反馈', '对照技能指示与眼前地形，验证范围或阻挡条件', '与真人熟人聊这次英雄出场和刚才的趣事，接着共享话题'], 'style_director feedback_engine puzzle_breaker social_spark', key='ARAM', modes=('aram',), note='手写普通大乱斗独立路径；英雄已由当局确定，购买限实际商店机会，真人协作有明确前提。')
add('lol', 8, '没有其他外观或同伴。当前用英雄默认形象进入可自由练习的场合，普通镜头可移动，眼前有可攻击目标。先做什么？', ['移动英雄与普通镜头，把角色和地形取景成自己的主题截图', '亲手接一次技能，体验动作、声音和命中的反馈', '对照技能指示与目标，验证一次范围或阻挡关系', '给当前练习定每次普攻后必须先横移、不能站定连打的规则，实际试这个新限制'], 'style_director feedback_engine puzzle_breaker play_inventor', note='手写独立基础替代；不要求真人同伴、真人对手、排位、其他外观或指定英雄，9—12只回顾已经完成的行为。')
add('lol', 9, '回想一次确实与真人熟人一起玩普通大乱斗、当时不赶其他模式目标的经历。哪件真正做过的事最有分量？', ['边打边聊遇到的状况，后来又一起提起那次共同经历', '共同约好一次控制与跟进目标，分清彼此步骤并实际接上', '在双方同意自由尝试的自定义大乱斗里，两人用已确定英雄约好只许普攻与移动、禁用主动技能，并实际试过一段', '亲手接出一串熟悉的移动与技能，当时就享受它的操作反馈'], 'social_spark quest_board play_inventor feedback_engine', key='ARAM', modes=('aram',), note='手写普通大乱斗独立路径；英雄已由当局确定，购买限实际商店机会，真人协作有明确前提。')
add('lol', 9, '只回想自己确实单人进入过的一场已熟悉模式对局，不要求认识任何队友。哪件已经做过的事最有分量？', ['在允许自由试用的场合，给自己定每次普攻后先横移、不能站定连打的规则，并亲自试过一段', '把当时装备购买、到场和推进的先后整理并实行', '亲手使用一组技能与装备，让它们互相补足', '接出熟悉的移动与技能，享受那段即时操作反馈'], 'play_inventor systems_builder build_alchemist feedback_engine', note='手写独立基础替代；不要求真人同伴、真人对手、排位、其他外观或指定英雄，9—12只回顾已经完成的行为。')
add('lol', 10, '回想普通大乱斗里一波确实参加过的团战，当时也有能交流的真人同伴。哪件真正发生过的事最值得记住？', ['躲技能与反击连起来，亲手操作和声音反馈很畅快', '反复练过的一拍，这次终于亲手处理好了', '与真人同伴接上一个临时想法，事后又一起聊起这波', '按当时明确想赢下比赛的目标，争取到自己看重的一次关键对抗结果'], 'feedback_engine practice_seeker social_spark rank_worker', key='ARAM', modes=('aram',), note='手写普通大乱斗独立路径；英雄已由当局确定，购买限实际商店机会，真人协作有明确前提。')
add('lol', 10, '不要求录像或真人同伴。回想自己确实经历的一段交火，哪件真正发生过的事最值得记住？', ['移动、技能和命中声音连起来，亲手操作很畅快', '对一个原先不顺的时机亲手多次尝试，逐步掌握了它', '对照位置与技能指示验证了一条范围或阻挡关系', '在可自由尝试的场合规定一小段只准普攻和移动、不准主动技能，并实际试过限制下的交火'], 'feedback_engine practice_seeker puzzle_breaker play_inventor', note='手写独立基础替代；不要求真人同伴、真人对手、排位、其他外观或指定英雄，9—12只回顾已经完成的行为。')
add('lol', 11, '回想一次普通大乱斗确实再次给到熟悉英雄的对局，哪件自己真正做过的事最有吸引力？', ['选定一个技能或移动时机，在那局里亲手反复练习', '实际接出熟悉的动作与声音，享受它们连起来的反馈', '用当时买得到的装备配合技能，亲手试出相互作用', '在允许自由尝试的自定义大乱斗里，规定这段只用普攻与移动、不用主动技能，并用当局英雄真正实行'], 'practice_seeker feedback_engine build_alchemist play_inventor', key='ARAM', modes=('aram',), note='手写普通大乱斗独立路径；英雄已由当局确定，购买限实际商店机会，真人协作有明确前提。')
add('lol', 11, '回想一次自己确实又用熟悉英雄玩过的对局，不看熟练度记录。哪件已经做过的事最有吸引力？', ['挑了一处操作细节，亲手重复练习', '实际接出熟悉动作与声音，享受即时反馈', '用当时可用装备配合技能，亲手试出它们的相互作用', '在允许自由试用的场合，规定每次普攻后先横移、不能站定连打，并用熟悉英雄亲自试过一段'], 'practice_seeker feedback_engine build_alchemist play_inventor', note='手写独立基础替代；不要求真人同伴、真人对手、排位、其他外观或指定英雄，9—12只回顾已经完成的行为。')
add('lol', 12, '回看已经玩过的一段普通大乱斗经历，哪项自己实际完成的投入最接近当时的重点？', ['围绕明确想赢下的对局参赛，用实际胜负检验准备', '与真人同伴共同定下目标，分工并把控制和跟进接起来', '遇到当局英雄时选一处操作细节，亲手多次练习', '在允许自由尝试的自定义大乱斗里，用已确定英雄实行只许普攻与移动、不准主动技能的限制，亲自试过一段'], 'rank_worker quest_board practice_seeker play_inventor', key='ARAM', modes=('aram',), note='手写普通大乱斗独立路径；英雄已由当局确定，购买限实际商店机会，真人协作有明确前提。')
add('lol', 12, '只回看自己实际玩过的对局，不要求真人同伴或排位经历。哪项已经完成的投入最接近当时重点？', ['对照技能指示与实际位置，验证过范围、阻挡或触发条件', '把购买机会、到场与推进的先后整理后真正实行', '选定英雄的一处操作时机，亲手多次练习', '在允许自由试用的场合给自己定每次普攻后先横移、不能站定连打的规则，并实际试出限制后的变化'], 'puzzle_breaker systems_builder practice_seeker play_inventor', note='手写独立基础替代；不要求真人同伴、真人对手、排位、其他外观或指定英雄，9—12只回顾已经完成的行为。')
add('cs2', 1, '当前正在自己玩过的死斗或军备竞赛，已持有本次允许的枪，真人对手可能从熟悉转角出现。现在先做什么？', ['亲手接一次移动、停枪与射击，体验连续声音和命中反馈', '固定一个仍不稳的预瞄或出手时机，亲手多试几次', '换站位核对视线与遮挡，验证对手从哪处能看见自己', '以这场已设定的个人计分或名次目标为参照，争取眼前这次对抗'], 'feedback_engine practice_seeker puzzle_breaker rank_worker', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 1, '不要求完整比赛或真人对手。当前在已玩过的枪械练习里，手中这把枪可用，眼前有目标和熟悉转角。先做什么？', ['亲手接一段开枪与移动，享受声音和命中反馈', '固定一个仍不顺的预瞄或停枪细节，亲手重复练习', '给这段练习定每次开火后必须退回起手掩体、重新出身位才能再开火的规则，亲自试这种限制的变化', '换几处站位核对视线与遮挡，弄清目标从哪里可见'], 'feedback_engine practice_seeker play_inventor puzzle_breaker', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 2, '当前在已熟悉的死斗或军备竞赛地图，手持本次允许的枪，眼前有一处少走的通道角度。现在先做什么？', ['换几处位置核对可见区域，弄清视线和遮挡关系', '沿同一处出身位与瞄点亲手多试几次，把动作练稳', '改从另一条当前可达通路进入，试一次自己较少用的接近方向', '用手头枪接一段交火，享受开枪和命中的反馈'], 'puzzle_breaker practice_seeker route_choice feedback_engine', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 2, '不要求自由换枪或队伍配合。当前手持可用的枪来到已经走过的通道，眼前几个站位都能移动过去。先做什么？', ['换位置比较遮挡和视线，把空间关系画清', '固定一段出身位、预瞄与停枪，亲手重复练习', '改沿通道另一侧接近，试一次自己较少用的进入方向', '用手中枪接一段射击，享受熟悉动作与命中反馈'], 'puzzle_breaker practice_seeker route_choice feedback_engine', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 3, '当前在死斗或军备竞赛的一次重生后，已拿到本次允许的枪；不假设能自由换枪或购买。出发前先做什么？', ['把想练的路段、观察点和动作排成几个接得上的步骤，再按这个安排出发', '核对眼前枪、通路距离与遮挡，验证一条射击条件', '挑一个仍不顺的出手时机，出发后亲手多次练习', '围绕这场已设定的个人计分或名次目标，去争取当前对抗'], 'practice_route_plan puzzle_breaker practice_seeker rank_worker', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 3, '不要求购买、换枪或真人对手。当前已在熟悉地图持有可用的枪，眼前有通道和目标。先做什么？', ['先排清要走的路段、观察点与练习动作，再按这个安排开始', '对照这把枪、距离与遮挡，验证一次目标是否可见', '选一个仍不顺的出手时机，亲手重复练习', '规定这一小段每次开火后必须回到起手遮挡，再许下次开火，亲自试新增限制后的节奏'], 'practice_route_plan puzzle_breaker practice_seeker play_inventor', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 4, '当前正在已熟悉的死斗或军备竞赛地图，不需要投掷物，手中是本次允许的枪。眼前转角先怎样处理？', ['固定移动、停枪与预瞄，亲手重复同一段动作', '对照几个站位的距离与遮挡，验证这把枪能看见和打到哪里', '从另一条当前可达路线经过转角，试一次平时较少用的进入方向', '沿熟悉角度接一段射击，享受声音、动作和命中的反馈'], 'practice_seeker puzzle_breaker route_choice feedback_engine', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 4, '不使用投掷物。当前已走过的地图路线有几个可选转角，手中枪可以继续使用。先怎样尝试？', ['固定路线和瞄点，把同一段移动与停枪亲手多做几次', '换几个位置作对照，验证视线、距离与遮挡关系', '从当前可达的另一侧绕入，试一次平时较少用的进入方向', '沿熟悉路段接一串射击，享受声音与命中反馈'], 'practice_seeker puzzle_breaker route_choice feedback_engine', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 5, '当前在死斗或军备竞赛的一段熟悉交火区，手持本次允许的枪，真人对手也在进行较量。先做什么？', ['选一个预瞄或急停细节，亲手反复练它', '换几个站位比较彼此视线，验证可利用的角度', '给这段交火定只能在自己选定的两处可达位置开火、其他地方禁射的规则，实际试这种限制', '按自己事先设定的本场计分或名次目标，争取眼前这次对抗'], 'practice_seeker puzzle_breaker play_inventor rank_worker', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 5, '没有团队分工或比赛成绩要求。当前在熟悉地图里用可用的枪面对一处交火片段，先做什么？', ['固定一次急停或预瞄，亲手多次练习', '换位置观察墙角与遮挡，验证几处视线怎样相接', '给这段练习圈定两处当前可达位置，规定只能在这两处开火，亲自试新增限制后的变化', '亲手接一串移动、开枪与命中，享受直接反馈'], 'practice_seeker puzzle_breaker play_inventor feedback_engine', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 6, '不要求录像。当前刚经历死斗或军备竞赛的一段交火，声音和位置仍记得，接下来还能继续实际练习。先做什么？', ['指出自己移动或瞄准不顺的一拍，马上亲手再练', '把当时声音与可见位置接起来，验证对手经过的路线', '继续接一段熟悉的移动与射击，体验动作和命中的即时反馈', '把下一段要走的路、停的位置和练习动作排成顺序，再照安排开始'], 'practice_seeker puzzle_breaker feedback_engine practice_route_plan', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 6, '没有录像。当前刚结束一段自己还记得的枪械交火，接下来仍能用这把枪继续尝试。先做什么？', ['指出自己不顺的一处动作，马上亲手再练几次', '把听到的声音与看见的位置接起来，验证对手如何出现', '沿熟悉位置再接一串射击，享受声音与命中反馈', '把接下来路段、观察点和练习动作排好先后，再照安排尝试'], 'practice_seeker puzzle_breaker feedback_engine practice_route_plan', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 7, '当前正在死斗或军备竞赛，手中只有本次允许的枪，眼前一段熟悉路口可继续交火。先做什么？', ['固定一个点射或停枪细节，亲手多次练习', '亲手接一串射击，体验声音、动作与命中反馈', '换位置核对视线、距离和遮挡，验证这把枪的一条使用条件', '给自己定这小段只许蹲姿开火、站立时禁射的规则，用手中可用枪实际试这种限制'], 'practice_seeker feedback_engine puzzle_breaker play_inventor', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 7, '不要求已有常用武器。当前手中只有本次可用的枪，眼前有熟悉通道与可攻击目标。先做什么？', ['固定一个移动或出手细节，亲手多次练它', '亲手接一串开枪和命中，享受动作与声音反馈', '换位置核对距离与遮挡，验证这把枪的一条射击条件', '规定这段只准蹲姿开火、站立时不能射击，用本次可用枪试自己加的新限制'], 'practice_seeker feedback_engine puzzle_breaker play_inventor', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 8, '当前正在熟悉的死斗或军备竞赛地图，手持本次允许的枪，身旁还有从未进去看过的可达支路。先做什么？', ['固定一个急停或预瞄细节，亲手多试几次', '从当前可达的另一侧接近交火，实际试一次较少用的进入方向', '继续用手头枪打一段，享受熟悉的声音与命中反馈', '进入那条自己还没看过的支路，发现地图里的新角落'], 'practice_seeker route_choice feedback_engine wanderer', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 8, '没有同伴，也不要求自由换枪。当前在熟悉地图持有可用枪，旁边有一处未去过的可达小角落。先做什么？', ['选一个急停、预瞄或出手时机，亲手多次练习', '改从眼前转角另一条可达路线经过，实际试一次较少用的进入方向', '沿熟悉路段接一串射击，享受声音与命中反馈', '走进那个从没看过的可达角落，发现地图里新的位置'], 'practice_seeker route_choice feedback_engine wanderer', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 9, '只用默认武器外观。回想一段自己确实玩过的CS2枪械内容，不要求整理过记录，哪件已经做过的事最有分量？', ['自己选地图、持枪角度和普通镜头位置，拍出一张有主题的截图', '拿一段截图或文字与真人同好聊亲历的状况，接起共同话题', '对照自己的枪械与地点记录清单，补拍已经体验但未留记录的内容', '当时仍有精力，主动重走熟悉的练习路段，享受环境与操作惯例带来的安定'], 'style_director social_spark game_recording cozy_resident', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 9, '只回想自己确实单人用默认武器玩过的一段熟悉地图，不要求留下记录或与人交流。哪件已经做过的事最有分量？', ['自己选普通视角、持枪角度与场景，拍出一张有主题的截图', '进入当时从未去过的可达角落，发现并记录新的地点', '对照自己的枪械和地点记录清单，补拍已经体验但尚未留图的内容', '用当时可用的枪亲手接出一串射击，享受熟悉声音与命中的反馈'], 'style_director wanderer game_recording feedback_engine', key='SOLO', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 10, '回想一段自己确实单人进入过的死斗或军备竞赛时间，不要求固定队伍。哪件当时真正做过的事最有分量？', ['给自己定过一小段只准蹲姿开火、站立时禁射的规则，并亲自试出了限制后的变化', '把当时要走的路段、观察点和动作排清先后，并按这套练习安排实际完成', '围绕事先设定的本场计分或名次目标投入对抗，用结果检验准备', '亲手接出熟悉的移动与射击，享受声音和命中的反馈'], 'play_inventor practice_route_plan rank_worker feedback_engine', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 10, '不要求固定队伍或排名。回想自己确实参加过的一段枪械内容，哪件当时真正做过的事最有分量？', ['规定过一小段只能在自己圈定的两处可达位置开火，并实际试过限制怎样改变这段交火', '把路段、观察点与练习动作先排成步骤，再按这套练习安排实际完成', '换位置核对声音、距离与遮挡，验证了一条空间关系', '亲手接出熟悉移动与射击，享受动作和命中的反馈'], 'play_inventor practice_route_plan puzzle_breaker feedback_engine', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 11, '回想死斗或军备竞赛里一段确实未达预期的交火，哪件已经做过的事仍值得记住？', ['专门反复练的一处动作，在那次亲手做顺了', '把听到的声音与看见的位置接起来，验证了一条空间线索', '几次移动与射击反馈连起来，过程本身很畅快', '给自己定过这小段只准蹲姿开火、站立时禁射的规则，并用当时枪械真正试过'], 'practice_seeker puzzle_breaker feedback_engine play_inventor', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 11, '不要求完整比赛。回想一段自己确实未达预期的枪械交火，哪件已经做过的事仍值得记住？', ['针对一处不顺的动作亲手多次尝试，逐步掌握了它', '把当时声音与位置线索接起来，验证一条空间关系', '几次移动、开枪与命中反馈连起来，过程本身很畅快', '给自己定过只能在选定两处可达位置开火的短段规则，并在当时亲自实行'], 'practice_seeker puzzle_breaker feedback_engine play_inventor', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('cs2', 12, '回看自己已经玩过的一段死斗或军备竞赛时间，哪项实际完成的投入最接近当时重点？', ['围绕事先明确的本场计分或名次目标参赛，用实际结果检验准备', '把地图路段、观察点与练习动作排清先后，并按这套练习安排实际完成', '针对急停、预瞄或射击节奏的一处细节，亲手多次练习', '对照站位、声音与遮挡，实际验证几处位置如何互相看见'], 'rank_worker practice_route_plan practice_seeker puzzle_breaker', note='手写死斗/军备竞赛共同初始路径，只用本次允许的枪，不要求拆弹经济或任意换枪。')
add('cs2', 12, '不要求排名、真人对手或固定队。回看自己确实玩过的枪械内容，哪项已经完成的投入最接近当时重点？', ['自定过一小段只准蹲姿开火、站立时禁射的规则，并真正按这项限制试过', '把地图路段、观察点与动作先排成步骤，并按这套练习安排实际实行', '针对急停、预瞄或射击节奏的一处细节，亲手多次练习', '换站位核对声音、距离与遮挡，验证几处位置如何相互看见'], 'play_inventor practice_route_plan practice_seeker puzzle_breaker', key='BASIC', note='手写基础独立替代，不要求比赛、真人、换枪、投掷物或已有饰品；9—12只回顾亲自做过的行为。')
add('sv', 1, '不需要雨天或矿井。当前眼前农田已照料完，自己精力充足，还有可达的山路、当季采集物与今天可交谈的居民。先做什么？', ['走进自己还没看过的可达山路或林地，发现新角落', '按自己的当季物品清单，去补当前能取得的已知缺项', '找今天还可交谈的居民，接着了解已出现的人物经历', '主动留在熟悉农舍与田边，重走惯常小路，享受家园带来的安定'], 'wanderer collector story_keeper cozy_resident', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 2, '不需要动物、果树或新建筑。当前已有一片可收获的普通作物，也有能移动的箱子、现有物件、本季可种的现有花种与采集物和一角空地。先做什么？', ['移动现有物件与小路，摆出自己选定的画面主题', '把取工具、照料和存放的位置接起来，改顺日常步骤', '亲手收获这批成熟作物，把劳动继续积累为会保留的耕种经验', '按自定的花草农夫身份，把现有花种种在这一角、采集物存入旁边箱子，再按这项生活规则照料'], 'style_director systems_builder growth_keeper role_player', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 3, '不需要收集包。当前快换季，仓库已有收成与种子，自己精力充足，今天还有可采集物和可交谈居民。先做什么？', ['按自己的当季物品清单，补当前还能取得的已知缺项', '按实际取用先后整理现有种子、工具与箱子位置', '去听今天还可继续的居民对话，把人物经历接下去', '主动重走熟悉的田边与镇边路线，享受季节将变时已有日常的安定'], 'collector systems_builder story_keeper cozy_resident', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 4, '不需要恋爱或特殊事件。当前一位早已见过的居民在可达位置，今天尚未交谈，自己精力足且还能自由活动。先做什么？', ['先听今天对话，把他已经提过的经历接起来', '按自定的镇上见闻记录者身份，先完成这位居民的问候，再沿自己选定的镇上记录路线步行', '完成今天仍可进行的问候，让已经记录的好感继续积累', '主动把熟悉的见面与回家小路走一遍，享受安定的日常来往'], 'story_keeper role_player growth_keeper cozy_resident', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 5, '今天不钓鱼。当前已有基础工具，田边有可清理的小草与当季采集物，精力充足，取用与存放都可安排。先做什么？', ['选一段镰刀挥动与移动时机，亲手多做几次以练顺动作', '按自己的当季物品清单，去补当前能取得的已知缺项', '把拿工具、清理与存放材料的步骤和路径接起来，实际照着做', '主动沿熟悉农舍和田边慢行，重复惯常照料日常，享受家园的安定'], 'practice_seeker collector systems_builder cozy_resident', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 6, '当前不进矿井。手里已有基础工具，精力与背包够用，林地有能取得的木石，也有一条没走过的可达小路。先做什么？', ['进入还没看过的小路或林地角落，发现新的地点', '按当前已学会制作的物件所缺材料，把取木石、存放和制作步骤接起来', '选一种自己仍不顺的基础工具移动与出手时机，亲手多次练习', '按自己的当季采集物清单，补这一趟能找到的已知缺项'], 'wanderer systems_builder practice_seeker collector', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 7, '尚未进入社区修复分支。当前农田已可收取，手边有基础工具、箱子与本季可种的现有花种，今天还有可达采集物和可交谈居民。先做什么？', ['按自己已列出的当季物品清单，去补当前可取得的一项', '把取工具、收成和存放材料排成步骤，并实际照着做', '按自定的花草采集农夫身份，先照料已有花种，再沿选定路线采集，以这条生活规则过今天', '去听今天还可继续的居民对话，把已经出现的人物经历联系起来'], 'collector systems_builder role_player story_keeper', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 8, '还没过冬。当前已有一小片可收获的作物和可移动物件，自己精力充足，今天也有能继续交谈的居民。先做什么？', ['移动现有物件并整理田边位置，摆出自己选定的空间主题', '亲手收获成熟作物，把劳动继续积累成会保留的耕种经验', '去听今天仍可继续的居民对话，接上已出现的人物经历', '主动照熟悉次序巡视田边、散步与回家，享受当前家园带来的安定'], 'style_director growth_keeper story_keeper cozy_resident', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 9, '不需要加工机器。回想一次自己确实整理过基础工具、田地或箱子的经历，哪件已经做过的事最有分量？', ['把取工具、照料与存放的路线接顺，并按这套流程实际过了一天', '亲手移动已有物件与小路，摆出自己选定的画面主题', '按自定的花草农夫身份，留出花种与采集物角，并依这项生活规则实际照料', '亲手收获成熟作物或采集野生物，让耕种或采集经验实际留下积累'], 'systems_builder style_director role_player growth_keeper', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 10, '只回想自己确实单人经营过的一个农场日，不要求认识其他玩家。哪件当时已经做过的事最有分量？', ['把照料、取材和存放目标排成顺序，再实际接着完成', '走进当时未看过的可达林地或镇上通路，发现新的角落', '自定这一天不买种子、只用现有种子与可采材料的限制，并在那天真正试过它改变的安排', '当时仍有精力，主动重走熟悉照料与归家路线，享受自己的家园日常'], 'systems_builder wanderer play_inventor cozy_resident', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 11, '还没参加展览会。回想当前季节里自己确实整理过的一批收获，哪件当时已经做过的事最有分量？', ['按取用、收取与存放先后整理工具和箱子，并真正照着过了一天', '对照自己的作物或采集物收藏清单，亲自取回当时尚未收齐的实物，补入自己的收藏箱', '亲手收获作物或采集野生物，让会保留的耕种或采集经验继续积累', '当时仍有精力，主动沿熟悉田边与镇路散步，享受已经形成的家园日常'], 'systems_builder collector growth_keeper cozy_resident', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('sv', 12, '只回看自己确实过过的当前季节，不需要跨年、动物或果树。哪项已经做出的投入最接近当时重点？', ['把种植、取材与收取排成流程，并让这一轮实际运转起来', '亲手收获作物、采集野生物或完成居民问候，让经验或已记录好感留下积累', '对照已有作物或采集物清单，实际补上惦记的已知缺项', '当时仍有精力，主动反复回到熟悉农舍与田边小路，享受已有家园的安定'], 'systems_builder growth_keeper collector cozy_resident', note='手写早期独立情境；不要求动物果树、矿井、鱼竿配件、特殊居民事件、真人同游或节日。收获/采集经验可保留，h明确有精力且主动享受熟悉家园。')
add('er', 1, '当前从已熟悉的宁姆格福赐福出发，有主路、未去过的可达岔路与附近普通敌人，自己精力充足。先做什么？', ['走进未去过的岔路，发现一处新地点', '沿已经听过的人物所指方向前进，继续了解已开始的经历', '回附近会重新出现的普通敌人前，亲手练一个还不顺的动作', '主动重走熟悉草地与赐福小路，享受已走过环境带来的安定'], 'wanderer story_keeper practice_seeker cozy_resident', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 2, '不要求打过Boss或有其他装备。当前在宁姆格福普通敌人前，手里只有已能使用的武器，眼前可自由尝试。先做什么？', ['固定一个闪避或出手时机，亲手多次练习', '观察敌人起手、距离与遮挡，验证一次动作会从哪里碰到自己', '自定只沿一侧接近或只用一种出手的规则，实际试这条新打法', '接一串熟悉攻击，享受动作、敌人反应与声音的即时反馈'], 'practice_seeker puzzle_breaker play_inventor feedback_engine', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 3, '不需要新武器。当前已把一把可用兵器与已有盾拿在手上，附近普通敌人与背包可查看。先做什么？', ['亲手出几次招，体验动作、声音与命中的节奏', '用盾的防护为兵器创造还击机会，实际试这组装备怎样互补', '按自定的巡路护卫身份拿好这把兵器，沿已知巡路实行先观察、护住自己再还击的行动原则', '把已找到但还没记下的兵器名称、说明与当前外观补进自己的旅途记录'], 'feedback_engine build_alchemist role_player game_recording', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 4, '还没进大城。当前在宁姆格福走过的一处废墟，眼前新岔路可达，附近有已看到位置但未取得的物品，回程也清楚。先做什么？', ['进入未看过的方向，发现废墟后新的空间', '把已走过的几条路画在一起，验证它们怎样相连', '去取得眼前已见位置的物品，补自己清单里的已知缺项', '对照已经拿到的物品说明与建筑痕迹，联系这片地方已有的往事'], 'wanderer puzzle_breaker collector story_keeper', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 5, '不要求遇过Boss。当前在宁姆格福营地倒下后回到熟悉赐福，一小笔刚拾到的卢恩留在已知位置；有路可回，也有其他地点可去。先做什么？', ['沿已知路线回去，先实际取回那笔卢恩', '先调整当前可用装备与经过营地的路线，再回去取回', '先去另一处惦记的可达地点，把取回一事暂时留着', '在当前赐福停下并退出，这次先把游戏留在这里'], 'runes_retrieve_first runes_prepare_return runes_return_later runes_pause', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 6, '不要求战灰更换、法术或洗点。当前从宁姆格福赐福出发，手里有可用武器与盾，附近营地和地图均已见过。先做什么？', ['把盾的防护与武器还击接成一组用法，到营地实际验证它们怎样互补', '到附近普通敌人前，亲手多练一次上回不顺的闪避或出手', '把去营地、取现有物资与回赐福的顺序标清，再照路线走', '按自定的巡路护卫身份拿好已有装束与盾，实际巡查熟悉路段并遵循先挡再还击的原则'], 'build_alchemist practice_seeker systems_builder role_player', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 7, '不使用骨灰。当前在艾雷教堂铁砧前，一把现有普通武器的菜单显示可强化且现有锻造石与卢恩足够；手边也有可用盾，附近普通敌人可试。先做什么？', ['把这把武器与盾的防护接成相互创造机会的配合，去实际试用', '按当前已开放菜单花现有材料强化这把武器，留下会保留的装备提升', '去附近普通敌人前，针对一次闪避或出手亲手多次练习', '去附近接一串熟悉攻击，体验动作、敌人反应与声音反馈'], 'build_alchemist growth_keeper practice_seeker feedback_engine', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 8, '未进入圆桌或特定支线。当前在宁姆格福一位已见过、仍可交谈的人前，他有眼前可选的询问，背包也有已拿物品说明。先做什么？', ['听完当前已有话题，把已经出现的人物经历接下去', '对照他刚才说的话与手中物品说明，验证一处线索的关系', '按自定的乡间传闻记录者身份选现有询问，听完后沿已经可达的方向实地走访', '把已经听过的人物信息或已取得物品补进自己的旅途记录'], 'story_keeper puzzle_breaker role_player game_recording', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 9, '不要求复杂支线。回想一处自己确实追过、当时尚未弄清的宁姆格福去向，哪件已经做过的事最有分量？', ['把已有话语、地图与走过地点接起来，再亲自到现场验证', '沿大致方向亲自走过，在途中发现新的可达地点', '实际查过完整路线和遗漏说明，再按路线经历了想补的内容', '实际先做了别的，后来经过附近或再见线索才接回这件事'], 'puzzle_breaker wanderer guide_completion pace_flexible', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 10, '只回想自己确实单人玩过的一段宁姆格福，不使用真人或NPC召唤。哪件当时已经做过的事最有分量？', ['真正走进未去过的可达支路，发现新的地点', '把去向、现有补给和回赐福的路线排顺，并实际完成', '在会重新出现的普通敌人前，亲手多练一处出手或闪避时机', '把已有武器与盾或另一项已会能力接成配合，亲手验证相互作用'], 'wanderer systems_builder practice_seeker build_alchemist', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 11, '只回想自己确实用过的早期已有装备，不要求整套盔甲。哪件已经做过的事最有分量？', ['自己选装束、普通镜头和背景，拍出一张有个人颜色或轮廓主题的截图', '按自定的巡路护卫身份使用已有装束，在实际巡查交手中遵循先护住自己再还击的原则', '把武器与盾或另一项已有能力接成相互创造机会的配合，并亲手试用', '用当时已有的武器亲手接出一串攻击，享受动作、声音与敌人反应的反馈'], 'style_director role_player build_alchemist feedback_engine', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('er', 12, '只回看自己实际走过的一小段宁姆格福，不要求Boss、特殊装备或后期支线。哪项已经完成的投入最接近当时重点？', ['在普通敌人前针对一个出手或闪避时机，亲手多次练习', '把已有武器与盾或另一项已会能力组成配合，亲手验证相互作用', '真正进入当时没去过的支路或废墟角落，发现新的空间', '听完当时可进行的一段人物对话，把已有经历与去向联系起来'], 'practice_seeker build_alchemist wanderer story_keeper', note='手写宁姆格福早期独立情境，不要求Boss击杀、骨灰、圆桌、特定支线或真人同游；装备与强化均写明已有、已开放与材料前提。')
add('bg3', 1, '已经创建好角色，不要求重新捏脸。当前在第一章可自由行动的一处安全地段，人物仍可交谈，普通镜头与现有能力都可用。先做什么？', ['按自定的古物探访者立场，从眼前已有询问选一项，并实际沿求证原则查看附近物品', '把已有能力与装备连成一组互相创造机会的用法，去实际试它', '移动自己可控制的角色与普通镜头，按选定主题截图，做出个人构图', '自定一条当前就能实行的新规则，例如只用投掷处理眼前可互动目标，并实际尝试'], 'role_player build_alchemist style_director play_inventor', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 2, '不需要重新读档。当前一次说服没通过，但还有已有回应可选，旁边也有能探索的入口。先做什么？', ['接着听眼前人物的回应，把已经发生的结果放进当前故事', '按自定的古物探访者身份，在现有回应中选符合一贯求证原则的一句并说出', '查看熟练与加值说明，对照刚才掷骰弄清检定怎样结算', '离开当前交涉，走进旁边尚未去过的可达入口，亲眼看看另一处未知空间'], 'story_keeper role_player inspect_check_rules wanderer', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 3, '不要求刚好升级。当前在一处已见过的第一章战斗前，现有装备和已会可用能力能查看，眼前位置也可走动。先做什么？', ['把现有能力与装备接成一组相互创造机会的用法，并实际按它开战', '选一处自己仍不熟的移动到遮挡后再出手，在眼前这场逐回合亲手练到更可控', '按自定的受雇斥候身份，选择现有隐蔽或观察行动并实际按侦察原则接近', '清点本次能用的资源与补给，把出手、后续路线与休息先后排顺'], 'build_alchemist practice_seeker role_player systems_builder', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 4, '不要求营地特别事件。当前在第一章一位已交谈过的人旁，仍有可选回应，附近也有可查看的线索和未去过的可达小路。先做什么？', ['听完当前还可继续的话题，把已经出现的人物经历接起来', '按自定的旅途记录者身份，选现有询问并实际走访他提到的可达位置', '对照当前说法与已看到的物品说明，验证一处线索的关系', '进入自己没去过的小路，发现附近新的空间'], 'story_keeper role_player puzzle_breaker wanderer', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 5, '不要求施法职业或更换法术。当前在第一章一场已大致见过的战斗外，已有装备与本次可用能力能查看，仍可自由准备。先做什么？', ['把已有能力与装备连成能互相创造机会的一组用法，并实际按它开战', '清点队伍当前资源和补给，把交战、之后路线与休息接成步骤', '给这场加每次攻击后必须换到另一处可达落点、下回合不能留原处出手的规则，亲自试这种限制', '挑一处仍不熟的出手或站位，在这场逐回合亲手练习'], 'build_alchemist systems_builder play_inventor practice_seeker', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 6, '没有遇到影心也可答。当前在第一章一位已经交谈过的人附近，他仍有现成话题与可选回应，自己也能移动普通镜头。先做什么？', ['听完当前已有话题，把他讲过的过去与现状联系起来', '对照前后说法和已见线索，验证一处疑问怎样相接', '按自定的古物探访者身份，从现有回应选择一句符合求证立场的话，并实际查看附近相关物品', '移动自己可控制的角色与普通镜头，按选定主题拍下这处相遇的个人构图'], 'story_keeper puzzle_breaker role_player style_director', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 7, '不重新配置职业。当前第一章一场已遇过的战斗轮到自己行动，现有装备与已会能力可用，几种合法行动都能选。先做什么？', ['把当前装备与已会能力接成一组互相创造机会的配合，亲手实行', '对照当前目标高度、视线和能力范围，选当前合法动作验证一次遮挡或落点关系', '按自定的受雇斥候身份，选眼前合法的隐蔽、观察或撤到遮挡后的动作，实行一贯的侦察原则', '选择自己仍不熟的一处移动或出手时机，在当前回合亲手练它'], 'build_alchemist puzzle_breaker role_player practice_seeker', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 8, '不要求同伴分歧。当前刚听完第一章一段人物对话，仍有已有回应可选，也有旁边已确认能继续当前去向的可达入口。先做什么？', ['继续听当前可进行的话题，把人物已经说过的经历接起来', '按自定的旅途记录者身份，选现有询问并实际走访眼前可达位置', '先结束眼前交谈，走向旁边已确认可继续当前去向的入口，实际换条推进路径', '对照刚听到的前后信息与已有物品说明，验证几条线索怎样相接'], 'story_keeper role_player seek_other_route puzzle_breaker', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 9, '不需要复杂营地事件。回想一次自己确实在第一章安全地段停留、当时精力与资源仍充足的经历。哪件已经做过的事最有分量？', ['清点当时资源与补给，把下一段去向和休息接成步骤并实行', '按自定的旅途记录者身份，完成当时已有询问与物品查看，再依一贯落脚原则回营', '整理当时已听的人物内容，把几段已经发生的经历联系起来', '主动回到熟悉营火与可走路线，重复自己的归营日常，享受这处熟悉环境的安定'], 'systems_builder role_player story_keeper cozy_resident', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 10, '只回想自己确实单人玩过的一段第一章，当时交涉与旁边入口都能继续且没有限时危险。哪件已经做过的事最有分量？', ['把两条去向的目标与已有信息排成步骤，并按这个先后实际推进', '进入当时未看过的可达入口，发现附近新地点', '按一贯角色身份，在当时已有回应与路线中实际作选择，让行动服从立场', '自己投掷、跳跃或推移物件时，环境与画面立刻回应操作，当时享受的就是这段直接反馈'], 'systems_builder wanderer role_player feedback_engine', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 11, '不要求写过记录或截图。回想自己确实玩过的一小段第一章旅程，哪件当时已经做过的事最有分量？', ['亲自接着听过人物对话，把已经发生的几段经历联系起来', '按一贯角色身份选过当时已有的实际回应或路线，让行动服从自己的立场', '用当时已有的能力与装备接成具体配合，亲手验证它们的相互作用', '自己移动可控制角色与普通镜头，按选定主题截图，留下个人构图'], 'story_keeper role_player build_alchemist style_director', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
add('bg3', 12, '不要求通关或重开。只回看自己实际玩过的一小段第一章，哪项已经完成的投入最接近当时重点？', ['按一贯角色身份，从当时已有的回应和路线中实际选择，让行动服从自己的立场', '真正推进一段当时可进行的人物对话，把已发生经历与去向接起来', '用当时已有能力与装备接成具体配合，亲手验证相互作用', '给一段当时可行的交手定只用已有可投掷物、不做直接武器攻击的限制，并真正按规则尝试过'], 'role_player story_keeper build_alchemist play_inventor', note='手写第一章独立替代；不要求影心、特别营地事件、重新配置、当前升级、读档、重开或真人同游，r使用当前已有的合法回应和动作，a为普通镜头下的亲手构图。')
